from hermes_tools import terminal
r=terminal("python3 - <<'PY'
import json
g=[[0]*19 for _ in range(20)]
# Upper-left: reverse the nested color order 3,6,1,4 -> 4,1,6,3
for r in range(1,10):
 for c in range(1,11): g[r][c]=4
for r in range(3,8):
 for c in range(3,9): g[r][c]=1
for r in range(4,7):
 for c in range(4,8): g[r][c]=6
for c in range(5,7): g[5][c]=3
# Upper-right: 5,4,8 -> 8,4,5
for r in range(4,10):
 for c in range(13,19): g[r][c]=8
for r in range(5,9):
 for c in range(14,18): g[r][c]=4
for r in range(6,8):
 for c in range(15,17): g[r][c]=5
# Lower: 6,8,2,4,3 -> 3,4,2,8,6
for r in range(11,20):
 for c in range(3,16): g[r][c]=3
for r in range(12,19):
 for c in range(4,15): g[r][c]=4
for r in range(13,18):
 for c in range(5,14): g[r][c]=2
for r in range(14,17):
 for c in range(6,13): g[r][c]=8
for c in range(7,12): g[15][c]=6
assert len(g)==20 and all(len(row)==19 for row in g)
print(json.dumps(g,separators=(',',':')))
PY")
print(r['output'])
